"use strict";
/**
 * Source-selected nonlinear LP2 p7/p8 generator candidate.
 * The physical p7 red word products [11,26,8,15,2] give GF29
 * fifth-order state coefficients AND initial state.
 * The physical p8 black body is 243 runes = 3^5, a complete nonlinear
 * five-trit lookup table. P8's red Roman-looking XIX suggests 19,
 * or its nineteenth Gematria prime 67 ≡9 mod29.
 *
 * Test additive GP29 stream generated by:
 * K_i=SUM(w_j*K_(i-j)) + q*X_(i-1), X=C or P,
 * key_i=T[trit(last five K_i)].
 *
 * No external key search, just {q:0,9,19} × 2 state driving choices ×
 * 2 trit maps × 2 emission clocks × 2 signs × 2 reset scopes.
 * Each candidate decrypts unchanged original GP indices and also passes
 * an independently encrypted source-native positive.
 *
 * SFT: node sims/lp2_p7p8_243trit_fivelag_nonlinear_stream_sft.cjs
 * Windows Node.js 22, original read-only corpus.
 */
const assert=require("node:assert/strict");
const fs=require("node:fs");
const path=require("node:path");
const {encodeSourceNativeGP}=require("./lp2_native_gp_source_orthography_sft.cjs");
const root=path.resolve(__dirname,"..");
const read=p=>fs.readFileSync(path.join(root,p),"utf8");
const gp=JSON.parse(read("resources/liber-primus/lp2-corpus.json"));
const w=[11,26,8,15,2];
const seed=w.slice();
const T=gp.pages[8].indices.slice(12);
assert.equal(T.length,243);
const red=[[23,3],[22,16,2,25],[5,7,11],[14,28],[6,28,19]];
const mod=x=>((x%29)+29)%29;
assert.deepEqual(gp.pages[7].indices.slice(-14),red.flat());
assert.deepEqual(red.map(x=>x.reduce((a,b)=>mod(a*b),1)),seed);
const toTrit={
  index:x=>x%3,
  prime:x=>gp.prime[x]%3
};
const lookup=(state,variant)=>{
  let index=0;
  for(let j=1;j<=5;j++)
    index=3*index+toTrit[variant](state[state.length-j]);
  assert(index>=0 && index<243);
  return T[index];
};
/**
 * @param {number[]} K
 * @param {number} drive
 * @param {number} q
 * @returns {number}
 */
function nextState(K,drive,q){
  let v=q*drive;
  for(let j=0;j<5;j++)
    v+=w[j]*K[K.length-j-1];
  return mod(v);
}
/**
 * @param {number[]} C
 * @param {{q:number,drive:"C"|"P",base:"index"|"prime",
 *  clock:"before"|"after",sign:number}} settings
 * @param {number[]} Kstart
 * @param {number} prevC
 * @param {number} prevP
 * @returns {{P:number[],K:number[],prevC:number,prevP:number}}
 */
function decrypt(C,settings,Kstart,prevC,prevP){
  const K=Kstart.slice(),P=[];
  const {q,drive,base,clock,sign}=settings;
  for(const c of C){
    if(clock==="after")
      K.push(nextState(K,drive==="C"?prevC:prevP,q));
    const p=mod(c+sign*lookup(K,base));
    if(clock==="before")
      K.push(nextState(K,drive==="C"?prevC:prevP,q));
    P.push(p);
    prevC=c;prevP=p;
  }
  return {P,K:K.slice(-5),prevC,prevP};
}
/**
 * Genuine source-native plant, with exact same state transition and
 * emission order as the above decoder.
 *
 * @param {number[]} P
 * @param {{q:number,drive:"C"|"P",base:"index"|"prime",
 *  clock:"before"|"after",sign:number}} settings
 * @param {number[]} Kstart
 * @param {number} prevC
 * @param {number} prevP
 * @returns {number[]}
 */
function encrypt(P,settings,Kstart,prevC,prevP){
  const K=Kstart.slice(),C=[];
  const {q,drive,base,clock,sign}=settings;
  for(const p of P){
    if(clock==="after")
      K.push(nextState(K,drive==="C"?prevC:prevP,q));
    const c=mod(p-sign*lookup(K,base));
    if(clock==="before")
      K.push(nextState(K,drive==="C"?prevC:prevP,q));
    C.push(c);
    prevC=c;prevP=p;
  }
  return C;
}
function ioc(input){
  const h=Array(29).fill(0);
  for(const x of input)h[x]++;
  return h.reduce((s,x)=>s+x*(x-1),0)/
    (input.length*(input.length-1));
}
let native=[];
for(const word of read("resources/control/gibran_prophet_58585.txt")
  .match(/[A-Za-z]+/g)||[]){
  const v=encodeSourceNativeGP(word);
  if(v)native.push(...v);
  if(native.length>=1500)break;
}
const clear=native.slice(0,1200);
assert.equal(clear.length,1200);
let planted=0;
for(const q of [0,9,19])
  for(const drive of ["C","P"])
    for(const base of ["index","prime"])
      for(const clock of ["before","after"])
        for(const sign of [-1,1]){
          const settings={q,drive,base,clock,sign};
          const C=encrypt(clear,settings,seed,seed[4],seed[4]);
          const answer=decrypt(C,settings,seed,seed[4],seed[4]);
          assert.deepEqual(answer.P,clear);
          planted++;
        }
assert.equal(planted,48);
const pages=gp.pages.filter(p=>p.page<=55);
assert.equal(pages.reduce((a,p)=>a+p.indices.length,0),12956);
const later=pages.filter(p=>p.page>=9);
const originalP9IoC=ioc(later.flatMap(p=>p.indices));
const tested=[];
for(const q of [0,9,19])
  for(const drive of ["C","P"])
    for(const base of ["index","prime"])
      for(const clock of ["before","after"])
        for(const sign of [-1,1])
          for(const reset of ["page","book"]){
            const settings={q,drive,base,clock,sign};
            let K=seed.slice(),prevC=seed[4],prevP=seed[4],out=[];
            for(const page of pages){
              if(reset==="page"){
                K=seed.slice();prevC=seed[4];prevP=seed[4];
              }
              const decoded=decrypt(page.indices,settings,K,prevC,prevP);
              K=decoded.K;prevC=decoded.prevC;prevP=decoded.prevP;
              if(page.page>=9)out.push(...decoded.P);
            }
            tested.push({...settings,reset,originalIoC:ioc(out)});
          }
tested.sort((a,b)=>b.originalIoC-a.originalIoC);
assert.equal(tested.length,96);
assert(Math.abs(originalP9IoC-0.03449302109588397)<1e-12);
assert(Math.abs(tested[0].originalIoC-0.03457185187369241)<1e-12);
assert(tested.every(x=>x.originalIoC<0.03458));
console.log(JSON.stringify({
  source:"original physical p7 five red-word GP29 products, p8 black 243-rune body, p8 Roman-like XIX and 19th GP prime",
  sourceTableLength:243,
  seed,
  candidates:96,
  hypotheticalFeedbackCoefficients:[0,9,19],
  model:"five-rune GF29 recurrence with prior ciphertext/plaintext feedback; nonlinear five-trit keyed p8 table emission",
  originalP9to55UnmodifiedIoC:originalP9IoC,
  bestOriginalIoC:tested[0],
  noOriginalCandidateExceeds:0.03458,
  nativeSourceIoC:ioc(clear),
  independentNativePositiveControls:planted,
  recoveredUnknownPlaintext:false,
  limits:"Neither the five-word product→recurrence nor p8 243→lookup interpretation is source-authenticated; trit coordinate permutations, unrelated keys, nonlinear state update and multistage encipherment remain untested"
},null,2));
